import {createContext, useContext, useMemo} from 'react'
import type {Pull} from '../types/pull'

interface DeprecatedPullContextType {
  pull: Pull
}

export const DeprecatedPullContext = createContext<DeprecatedPullContextType | undefined>(undefined)

export function useDeprecatedPullContext() {
  const context = useContext(DeprecatedPullContext)
  if (!context) {
    throw new Error('useDeprecatedPullContext must be used within a DeprecatedPullContextProvider')
  }
  return context
}

interface DeprecatedPullContextProviderProps extends DeprecatedPullContextType {
  children: React.ReactNode
}

export function DeprecatedPullContextProvider({pull, children}: DeprecatedPullContextProviderProps) {
  const value = useMemo(() => ({pull}), [pull])
  return <DeprecatedPullContext.Provider value={value}>{children}</DeprecatedPullContext.Provider>
}

try{ DeprecatedPullContext.displayName ||= 'DeprecatedPullContext' } catch {}
try{ DeprecatedPullContextProvider.displayName ||= 'DeprecatedPullContextProvider' } catch {}